function summary=calculateScenarioStatistics(trades,cfg,profile)
summary=struct("profile",profile.name,"totalSessions",height(trades),"executedTrades",0,"skippedTrades",0,"winningTrades",0,"losingTrades",0,"breakevenTrades",0,"winRatePct",NaN,"netR",0,"netPnLUSD",0,"commissionsUSD",0,"profitFactor",NaN,"expectancyR",NaN,"maxDrawdownUSD",NaN,"maxDrawdownPct",NaN,"finalEquityUSD",cfg.risk.initialEquityUSD,"minimumEquityUSD",cfg.risk.initialEquityUSD,"averageContracts",NaN,"maximumContracts",0,"stopTrades",0,"targetTrades",0,"breakEvenExitTrades",0,"trailingStopTrades",0,"eodTrades",0);
if isempty(trades), return; end
executed=trades(trades.valid,:); skipped=trades(~trades.valid,:); summary.executedTrades=height(executed); summary.skippedTrades=height(skipped); if isempty(executed), return; end
pnl=executed.net_pnl_usd; r=executed.net_R; summary.winningTrades=nnz(pnl>0); summary.losingTrades=nnz(pnl<0); summary.breakevenTrades=nnz(pnl==0); summary.winRatePct=100*summary.winningTrades/height(executed); summary.netR=sum(r,"omitnan"); summary.netPnLUSD=sum(pnl,"omitnan"); summary.commissionsUSD=sum(executed.commission_usd,"omitnan"); summary.expectancyR=mean(r,"omitnan"); summary.finalEquityUSD=executed.equity_after_usd(end); summary.minimumEquityUSD=min(executed.equity_after_usd); if ismember("quantity",string(executed.Properties.VariableNames)), q=executed.quantity; else, q=executed.contracts; end; summary.averageContracts=mean(q); summary.maximumContracts=max(q);
wins=pnl(pnl>0); losses=pnl(pnl<0); gp=sum(wins); gl=abs(sum(losses)); if gl>0, summary.profitFactor=gp/gl; elseif gp>0, summary.profitFactor=Inf; end
equity=[cfg.risk.initialEquityUSD; executed.equity_after_usd]; peak=cummax(equity); dd=equity-peak; ddPct=100*dd./peak; summary.maxDrawdownUSD=abs(min(dd)); summary.maxDrawdownPct=abs(min(ddPct)); summary.stopTrades=nnz(executed.exit_reason=="STOP"); summary.targetTrades=nnz(executed.exit_reason=="TARGET"); summary.breakEvenExitTrades=nnz(executed.exit_reason=="BREAKEVEN"); summary.trailingStopTrades=nnz(executed.exit_reason=="TRAILING_STOP"); summary.eodTrades=nnz(executed.exit_reason=="EOD");
end
